def calcular_totais(pedidos):
    totais = []
    total_geral = 0
    for pedido in pedidos:
        subtotal = 0
        for item in pedido['itens']:
            subtotal += item['quantidade'] * item['preco']
        totais.append({
            'cliente': pedido['cliente'],
            'total_pedido': subtotal
        })
        total_geral += subtotal
    return totais, total_geral
